import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trash2, Plus, Play, Clock, Calendar, Download, 
  ShieldCheck, Globe, Home, BookOpen, ChevronRight, 
  Settings2, Users, RefreshCw, CheckCircle2, AlertCircle, 
  LayoutGrid, AlertTriangle, Edit3, ArrowUp, ArrowDown, Lock, X, Info
} from 'lucide-react';

// --- HELPER FUNCTIONS ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${suffix}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const totalH = h + hours;
  return `${String(totalH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ 
  dept, 
  onUpdate, 
  onGenerate, 
  onDeleteDept, 
  onClearSchedule, 
  globalSchedule = [], 
  allDepartments = [] 
}) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [generationErrors, setGenerationErrors] = useState([]); 
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- MANUAL POWER LAYER STATES ---
  const [localSchedule, setLocalSchedule] = useState([]);
  const [auditLog, setAuditLog] = useState([]);
  const [toast, setToast] = useState(null);
  const [previousScheduleState, setPreviousScheduleState] = useState([]); // For Undo

  // Modals
  const [flagModal, setFlagModal] = useState({ isOpen: false, targetId: null, note: "" });
  const [proctorModal, setProctorModal] = useState({ isOpen: false, targetSub: null, pool: 'Department' });
  const [roomModal, setRoomModal] = useState({ isOpen: false, targetBlock: null, pool: 'Department' });
  const [summaryModalIsOpen, setSummaryModalIsOpen] = useState(false);

  // Sync initial preview if globalSchedule has data for us, but prefer local draft if active
  useEffect(() => {
      if (localSchedule.length === 0) {
          setLocalSchedule(globalSchedule.filter(s => s.dept_code === deptCode));
      }
  }, [globalSchedule, deptCode]);

  const showToast = (message, type = 'success', undoable = false) => {
      setToast({ message, type, undoable });
      if (!undoable && type === 'success') setTimeout(() => setToast(null), 5000);
  };

  const undoLastChange = () => {
      if (previousScheduleState.length > 0) {
          setLocalSchedule(previousScheduleState);
          setAuditLog(prev => [...prev, "Reverted last change due to conflict."]);
          setToast(null);
      }
  };

  // 9.5 RE-VALIDATION ENGINE
  const validateAndApplyChange = (newSchedule, logMessage) => {
      const combined = [...globalSchedule.filter(s => s.dept_code !== deptCode), ...newSchedule];
      const conflicts = [];

      for (let i = 0; i < combined.length; i++) {
         for (let j = i + 1; j < combined.length; j++) {
            const a = combined[i]; const b = combined[j];
            if (a.exam_date === b.exam_date) {
               // Hard constraint: No proctor overlapping at the same time
               if (a.proctor === b.proctor && a.start_time < b.end_time && a.end_time > b.start_time) {
                   conflicts.push(`Proctor ${a.proctor} has overlapping sessions at ${formatTime(a.start_time)}`);
               }
               // Hard constraint: No room overlapping at the same time
               if (a.room === b.room && a.start_time < b.end_time && a.end_time > b.start_time) {
                   conflicts.push(`Room ${a.room} is double-booked at ${formatTime(a.start_time)}`);
               }
            }
         }
      }

      if (conflicts.length > 0) {
          showToast(`Conflict Detected: ${conflicts[0]}`, 'error', true);
          return false;
      }

      setPreviousScheduleState(localSchedule);
      setLocalSchedule(newSchedule);
      setAuditLog(prev => [...prev, logMessage]);
      showToast(`✅ ${logMessage}`);
      return true;
  };

  // --- ENHANCED PREVIEW ENGINE (Grouping Logic Modified for Manual Power) ---
  const consolidatedPreview = useMemo(() => {
    const deptData = localSchedule; 
    const groups = {};
    const today = new Date().toISOString().split('T')[0];

    deptData.forEach(item => {
      // Grouping adjusted: Removing proctor from key so subjects can have DIFFERENT proctors in same block
      const groupKey = `${item.section}-${item.exam_date}-${item.room}`;

      if (!groups[groupKey]) {
        let currentStatus = item.status || 'COMMITTED';
        if (item.exam_date < today) currentStatus = 'DONE';

        groups[groupKey] = {
          section: item.section,
          date: item.exam_date,
          year: item.year_level,
          room: item.room,
          status: currentStatus, 
          startTime: item.start_time,
          endTime: item.end_time,
          subs: []
        };
      }

      groups[groupKey].subs.push({
        id: item.id,
        code: item.subject_code,
        name: item.subject_name,
        slot: `${formatTime(item.start_time)} - ${formatTime(item.end_time)}`,
        startTime: item.start_time,
        endTime: item.end_time,
        proctor: item.proctor,
        flagged: item.flagged,
        flagNote: item.flagNote,
        isManualProctor: item.isManualProctor
      });

      if (item.start_time < groups[groupKey].startTime) groups[groupKey].startTime = item.start_time;
      if (item.end_time > groups[groupKey].endTime) groups[groupKey].endTime = item.end_time;
    });

    return Object.values(groups).map(g => ({
      ...g,
      subs: g.subs.sort((a, b) => a.startTime.localeCompare(b.startTime))
    })).sort((a, b) => new Date(a.date) - new Date(b.date) || a.section.localeCompare(b.section));
  }, [localSchedule, deptCode]);

  const tablesByYearAndDay = useMemo(() => {
    const data = {};
    consolidatedPreview.forEach(item => {
      if (!data[item.year]) data[item.year] = {};
      if (!data[item.year][item.date]) data[item.year][item.date] = [];
      data[item.year][item.date].push(item);
    });
    return data;
  }, [consolidatedPreview]);

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const handleGenerateClick = () => {
    setGenerationErrors([]);
    const errors = [];
    const yearSubs = subjects[selectedYear] || [];

    if (yearSubs.length === 0) errors.push({ issue: "No Subjects", resolution: `Add subjects for Year ${selectedYear} first.` });
    if (examDays === 0 || sectionCount === 0) errors.push({ issue: "Config Error", resolution: "Set Exam Days and Section Count." });
    if (examDates.some(d => !d)) errors.push({ issue: "Missing Timeline", resolution: "Assign a date to every exam day." });

    if (errors.length > 0) {
      setGenerationErrors(errors);
      return; 
    }

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      if (daySubjects.length === 0) continue; 

      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));

      const uniqueOtherRooms = otherRooms.filter((v, i, a) => a.findIndex(t => (t.number === v.number)) === i);
      let availableRooms = roomSource === "Department" ? [...localRooms, ...uniqueOtherRooms] : [...uniqueOtherRooms, ...localRooms];

      const isProctorFree = (p) => {
          const isAvailableTime = dayDate >= p.dayStart && dayDate <= p.dayEnd &&
                                  startTime >= p.timeStart && endTime <= p.timeEnd;
          const isUsedGloballyToday = globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate);
          return isAvailableTime && !isUsedGloballyToday;
      };

      const localProctors = proctors.filter(isProctorFree);
      const otherProctors = globalProctorPool.filter(p => !proctors.find(dp => dp.name === p.name) && isProctorFree(p));

      const uniqueOtherProctors = otherProctors.filter((v, i, a) => a.findIndex(t => (t.name === v.name)) === i);
      let availableProctors = proctorSource === "Department" ? [...localProctors, ...uniqueOtherProctors] : [...uniqueOtherProctors, ...localProctors];

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        if (availableRooms.length === 0) {
            errors.push({ issue: `Room Overlap (Day ${d+1})`, resolution: `No available rooms for Section ${sectionID} on ${dayDate}. Add more concurrent rooms.` });
        } 
        if (availableProctors.length === 0) {
            errors.push({ issue: `Proctor Overlap (Day ${d+1})`, resolution: `No proctors for Section ${sectionID} on ${dayDate}. Proctors are restricted to 1 session/day.` });
        }

        if (availableRooms.length > 0 && availableProctors.length > 0) {
            const selectedRoom = availableRooms.shift();
            const selectedProctor = availableProctors.shift();

            daySubjects.forEach((sub, idx) => {
              finalGeneratedData.push({
                id: `${sectionID}-${dayDate}-${idx}-${Date.now()}`, // Added unique ID for manual overriding
                subject_code: sub.code, subject_name: sub.name, section: sectionID,
                year_level: selectedYear, dept_code: deptCode, exam_date: dayDate,
                start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1),
                room: selectedRoom.number, proctor: selectedProctor.name,
                status: 'ACTIVE', flagged: false, flagNote: '', isManualProctor: false
              });
            });
        }
      }
    }

    if (errors.length > 0) {
      setGenerationErrors(errors);
      return; 
    }

    // Set local state to activate Manual Power Mode
    setLocalSchedule(finalGeneratedData);
    setAuditLog(["Automated Generation Completed."]);
    setActiveTab("preview");
  };

  // --- MANUAL ACTIONS ---
  const handleFlagSubmit = () => {
      const updated = localSchedule.map(s => s.id === flagModal.targetId ? { ...s, flagged: true, flagNote: flagModal.note } : s);
      validateAndApplyChange(updated, `Flagged emergency for subject in ${updated.find(s => s.id === flagModal.targetId).section}. Note: ${flagModal.note}`);
      setFlagModal({ isOpen: false, targetId: null, note: "" });
  };

  const handleProctorSwitch = (newProctorName) => {
      const target = proctorModal.targetSub;

      // Automatic Reliever Detection (Simplified for this scope: Just prevents selection if strictly overlapping)
      const isOverlapping = [...globalSchedule, ...localSchedule].some(s => 
          s.proctor === newProctorName && s.exam_date === target.date && s.id !== target.id &&
          ((target.startTime >= s.start_time && target.startTime < s.end_time) || (target.endTime > s.start_time && target.endTime <= s.end_time))
      );

      if (isOverlapping) {
          showToast(`Cannot switch. Proctor ${newProctorName} is double-booked. Suggestion: Find Reliever or extend window.`, 'error');
          return;
      }

      const updated = localSchedule.map(s => s.id === target.id ? { ...s, proctor: newProctorName, isManualProctor: true, flagged: false, flagNote: '' } : s);
      const success = validateAndApplyChange(updated, `Manually switched proctor to ${newProctorName} for ${target.code} (${formatTime(target.startTime)} - ${formatTime(target.endTime)}).`);
      if (success) setProctorModal({ isOpen: false, targetSub: null });
  };

  const handleRoomSwitch = (newRoomNumber) => {
      const target = roomModal.targetBlock; // contains section, date, room
      const updated = localSchedule.map(s => (s.section === target.section && s.exam_date === target.date) ? { ...s, room: newRoomNumber } : s);
      const success = validateAndApplyChange(updated, `Manually switched room to ${newRoomNumber} for block ${target.section} on ${target.date}.`);
      if (success) setRoomModal({ isOpen: false, targetBlock: null });
  };

  const handleMoveSubject = (block, idx, direction) => {
      if (idx + direction < 0 || idx + direction >= block.subs.length) return;
      const subA = block.subs[idx];
      const subB = block.subs[idx + direction];

      const updated = localSchedule.map(s => {
          if (s.id === subA.id) return { ...s, start_time: subB.startTime, end_time: subB.endTime };
          if (s.id === subB.id) return { ...s, start_time: subA.startTime, end_time: subA.endTime };
          return s;
      });
      validateAndApplyChange(updated, `Manually reordered succession for subjects ${subA.code} and ${subB.code}.`);
  };

  const handleApproveAndLock = () => {
      onGenerate(localSchedule, examDates); // Assuming this bubbles up to global store
      setAuditLog([]);
      setSummaryModalIsOpen(false);
      showToast("Schedule Locked and globally validated.", "success");
  };

  const renderStatusBadge = (status) => {
    switch(status) {
      case 'ACTIVE': 
        return <span className="flex items-center gap-2 bg-emerald-500 text-white px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest shadow-lg animate-pulse"><Play size={10} fill="white"/> ACTIVE</span>;
      case 'DONE':
        return <span className="flex items-center gap-2 bg-slate-800 text-slate-400 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border border-slate-700"><CheckCircle2 size={10}/> DONE</span>;
      default: 
        return <span className="flex items-center gap-2 bg-blue-50 text-blue-600 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border border-blue-200"><ShieldCheck size={10}/> COMMITTED</span>;
    }
  };

  return (
    <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden mb-16 transition-all hover:shadow-blue-500/5 relative">

      {/* TOAST NOTIFICATION SYSTEM */}
      {toast && (
          <div className={`absolute bottom-10 right-10 z-50 p-6 rounded-2xl shadow-2xl flex items-center gap-4 text-white font-black text-xs uppercase tracking-widest animate-in slide-in-from-bottom-5 ${toast.type === 'error' ? 'bg-rose-600' : 'bg-emerald-600'}`}>
              {toast.type === 'error' ? <AlertCircle size={20}/> : <CheckCircle2 size={20}/>}
              <span>{toast.message}</span>
              {toast.undoable && (
                  <button onClick={undoLastChange} className="ml-4 bg-white/20 hover:bg-white/30 px-4 py-2 rounded-xl transition-all flex items-center gap-2">
                      <RefreshCw size={14} /> UNDO
                  </button>
              )}
              {!toast.undoable && <button onClick={() => setToast(null)}><X size={16} className="opacity-50 hover:opacity-100"/></button>}
          </div>
      )}

      {/* HEADER SECTION */}
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 via-emerald-500 to-amber-500"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4">
            <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none">{deptName}</h2>
            <button onClick={() => onDeleteDept(deptId, deptCode)} className="bg-rose-500/20 hover:bg-rose-500 text-rose-500 hover:text-white p-2 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
          <p className="text-blue-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3 flex items-center gap-2">
            <Settings2 size={12}/> Departmental Workspace Engine
          </p>
        </div>
        <div className="flex gap-4 relative z-10">
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
                <span className="block text-[8px] font-black text-blue-400 uppercase tracking-widest mb-1">Proctor</span>
                <span className="text-2xl font-black">{proctors.length}</span>
            </div>
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
