                                            <div>
                                                <span className="text-sm font-black text-blue-600">{s.code}</span>
                                                <span className="block text-[9px] font-black text-slate-400 uppercase italic tracking-tighter mt-1">{s.slot}</span>
                                            </div>
                                            {/* MANUAL POWER: SUBJECT REORDERING */}
                                            <div className="flex flex-col gap-1 bg-slate-50 p-1 rounded-lg">
                                                <button onClick={() => handleMoveSubject(row, idx, -1)} className="text-slate-300 hover:text-blue-600"><ArrowUp size={14}/></button>
                                                <button onClick={() => handleMoveSubject(row, idx, 1)} className="text-slate-300 hover:text-blue-600"><ArrowDown size={14}/></button>
                                            </div>
                                        </div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase mt-4 leading-snug">{s.name}</p>

                                        <div className={`mt-4 pt-4 border-t flex justify-between items-center ${s.flagged ? 'border-orange-200' : 'border-slate-100'}`}>
                                            {/* MANUAL POWER: PROCTOR SWITCH */}
                                            <button onClick={() => setProctorModal({ isOpen: true, targetSub: { ...s, date: row.date }, pool: 'Department' })} className={`text-[9px] font-black uppercase flex items-center gap-1.5 transition-colors ${s.isManualProctor ? 'text-blue-600' : 'text-slate-600 hover:text-blue-600'}`}>
                                                <Users size={12}/> <span className="truncate max-w-[80px]">{s.proctor}</span> <Edit3 size={10}/>
                                            </button>
                                            {/* MANUAL POWER: EMERGENCY FLAG */}
                                            <button onClick={() => setFlagModal({ isOpen: true, targetId: s.id, note: s.flagNote })} className={`p-1.5 rounded-lg transition-colors ${s.flagged ? 'bg-orange-100 text-orange-600' : 'hover:bg-slate-100 text-slate-300 hover:text-orange-500'}`}>
                                                <AlertTriangle size={14}/>
                                            </button>
                                        </div>
                                        {s.flagNote && <div className="mt-3 bg-orange-100 text-orange-800 text-[8px] font-bold p-2 rounded-lg italic break-words">NOTE: {s.flagNote}</div>}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-32 bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-100">
                        <RefreshCw size={48} className="text-slate-200 mx-auto mb-6 animate-spin-slow" />
                        <p className="text-slate-300 font-black uppercase tracking-[0.4em] text-xs">No active draft found</p>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>

      {/* --- MODALS FOR MANUAL POWER LAYER --- */}

      {/* 9.1 Emergency Flagging Modal */}
      {flagModal.isOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm">
              <div className="bg-white w-full max-w-md p-8 rounded-[2.5rem] shadow-2xl animate-in zoom-in-95">
                  <div className="flex items-center gap-4 text-orange-500 mb-6">
                      <AlertTriangle size={32} />
                      <h3 className="text-xl font-black uppercase tracking-tighter text-slate-900">Flag Emergency</h3>
                  </div>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4">A replacement proctor will be required before final lock.</p>
                  <textarea 
                      value={flagModal.note} onChange={(e) => setFlagModal({...flagModal, note: e.target.value})}
                      placeholder="e.g. Proctor John Lee - family emergency..."
                      className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl text-xs font-bold outline-none focus:border-orange-500 h-32 resize-none mb-6"
                  />
                  <div className="flex gap-4">
                      <button onClick={() => setFlagModal({ isOpen: false, targetId: null, note: "" })} className="flex-1 p-4 rounded-xl font-black text-[10px] uppercase text-slate-500 bg-slate-100 hover:bg-slate-200 transition-colors">Cancel</button>
                      <button onClick={handleFlagSubmit} disabled={!flagModal.note} className="flex-1 p-4 rounded-xl font-black text-[10px] uppercase text-white bg-orange-500 hover:bg-orange-600 disabled:opacity-50 transition-colors">Apply Flag</button>
                  </div>
              </div>
          </div>
      )}

      {/* 9.2 Proctor Switching Modal */}
      {proctorModal.isOpen && proctorModal.targetSub && (() => {
          const t = proctorModal.targetSub;
          const targetProctors = proctorModal.pool === 'Department' ? proctors : globalProctorPool;
          const availableList = targetProctors.filter(p => p.dayStart <= t.date && p.dayEnd >= t.date && p.timeStart <= t.startTime && p.timeEnd >= t.endTime);

          return (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm">
              <div className="bg-white w-full max-w-lg p-8 rounded-[3rem] shadow-2xl animate-in zoom-in-95">
                  <h3 className="text-2xl font-black uppercase tracking-tighter text-slate-900 mb-2">Switch Proctor</h3>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-6 border-b-2 border-slate-50 pb-6 flex items-center gap-2">
                      <Clock size={12}/> {t.code} • {t.date} • {formatTime(t.startTime)} - {formatTime(t.endTime)}
                  </p>

                  <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                      <button onClick={() => setProctorModal({...proctorModal, pool: 'Department'})} className={`flex-1 py-3 text-[9px] font-black uppercase rounded-lg ${proctorModal.pool === 'Department' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>Department Pool</button>
                      <button onClick={() => setProctorModal({...proctorModal, pool: 'Global'})} className={`flex-1 py-3 text-[9px] font-black uppercase rounded-lg ${proctorModal.pool === 'Global' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>Global Pool</button>
                  </div>

                  <div className="max-h-64 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                      {availableList.length === 0 && <p className="text-center text-[10px] font-bold text-slate-400 py-8 uppercase">No available staff in this timeframe.</p>}
                      {availableList.map((p, idx) => (
                          <div key={idx} onClick={() => handleProctorSwitch(p.name)} className="flex justify-between items-center p-4 rounded-2xl border-2 border-slate-50 hover:border-blue-200 cursor-pointer group transition-all">
                              <span className="font-black text-xs text-slate-800 uppercase">{p.name}</span>
                              <span className="text-[8px] font-black uppercase bg-slate-100 text-slate-500 px-3 py-1 rounded-full group-hover:bg-blue-600 group-hover:text-white transition-colors">Assign</span>
                          </div>
                      ))}
                  </div>

                  <div className="mt-6 pt-6 border-t-2 border-slate-50">
                      <button onClick={() => setProctorModal({ isOpen: false, targetSub: null })} className="w-full p-4 rounded-2xl font-black text-[10px] uppercase text-slate-500 hover:bg-slate-50 transition-colors">Cancel Override</button>
                  </div>
              </div>
          </div>
          );
      })()}

      {/* 9.3 Room Switching Modal */}
      {roomModal.isOpen && roomModal.targetBlock && (() => {
          const tb = roomModal.targetBlock;
          const targetRooms = roomModal.pool === 'Department' ? rooms : globalRoomPool;
          const availableList = targetRooms.filter(r => 
              !localSchedule.some(s => s.room === r.number && s.exam_date === tb.date && (tb.startTime < s.end_time && tb.endTime > s.start_time) && s.section !== tb.section)
          );

          return (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm">
              <div className="bg-white w-full max-w-md p-8 rounded-[3rem] shadow-2xl animate-in zoom-in-95">
                  <h3 className="text-2xl font-black uppercase tracking-tighter text-slate-900 mb-2">Switch Block Room</h3>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-6 border-b-2 border-slate-50 pb-6 flex items-center gap-2">
                      <Home size={12}/> Section {tb.section} • {formatTime(tb.startTime)} - {formatTime(tb.endTime)}
                  </p>

                  <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
                      <button onClick={() => setRoomModal({...roomModal, pool: 'Department'})} className={`flex-1 py-3 text-[9px] font-black uppercase rounded-lg ${roomModal.pool === 'Department' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>Department Pool</button>
                      <button onClick={() => setRoomModal({...roomModal, pool: 'Global'})} className={`flex-1 py-3 text-[9px] font-black uppercase rounded-lg ${roomModal.pool === 'Global' ? 'bg-white shadow text-blue-600' : 'text-slate-400'}`}>Global Pool</button>
                  </div>

                  <div className="grid grid-cols-3 gap-3 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                      {availableList.length === 0 && <p className="col-span-3 text-center text-[10px] font-bold text-slate-400 py-8 uppercase">No rooms free for full block.</p>}
                      {availableList.map((r, idx) => (
                          <div key={idx} onClick={() => handleRoomSwitch(r.number)} className="text-center p-4 rounded-2xl border-2 border-slate-50 hover:border-blue-500 cursor-pointer hover:bg-blue-50 transition-all font-black text-slate-800 text-lg">
                              {r.number}
                          </div>
                      ))}
                  </div>

                  <div className="mt-6 pt-6 border-t-2 border-slate-50">
                      <button onClick={() => setRoomModal({ isOpen: false, targetBlock: null })} className="w-full p-4 rounded-2xl font-black text-[10px] uppercase text-slate-500 hover:bg-slate-50 transition-colors">Cancel Override</button>
                  </div>
              </div>
          </div>
          );
      })()}

      {/* 9.4 Final Confirmation Summary Modal */}
      {summaryModalIsOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md">
              <div className="bg-white w-full max-w-2xl p-12 rounded-[3.5rem] shadow-2xl animate-in zoom-in-95">
                  <div className="flex items-center gap-4 text-emerald-500 mb-2">
                      <Lock size={32} />
                      <h3 className="text-3xl font-black uppercase tracking-tighter text-slate-900">Approve & Lock Schedule</h3>
                  </div>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-8">Pre-flight Validation & Audit Summary</p>

                  <div className="bg-slate-50 border-2 border-slate-100 rounded-3xl p-6 mb-8">
                      <div className="flex items-center gap-3 text-[10px] font-black uppercase text-emerald-600 mb-4 pb-4 border-b border-slate-200">
                          <CheckCircle2 size={16}/> Global Validation Passed - 0 Conflicts Detected
                      </div>
                      <div className="max-h-40 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                          {auditLog.length === 0 ? (
                              <p className="text-[10px] text-slate-400 font-bold uppercase italic">No manual overrides were applied.</p>
                          ) : (
                              auditLog.map((log, idx) => (
                                  <div key={idx} className="text-[10px] font-bold text-slate-700 bg-white p-3 rounded-xl border border-slate-100 flex items-start gap-2">
                                      <Info size={12} className="text-blue-500 mt-0.5 shrink-0"/> {log}
                                  </div>
                              ))
                          )}
                      </div>
                  </div>

                  <div className="flex gap-4">
                      <button onClick={() => setSummaryModalIsOpen(false)} className="flex-1 p-5 rounded-2xl font-black text-[10px] uppercase text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors">Back to Editing</button>
                      <button onClick={handleApproveAndLock} className="flex-1 p-5 rounded-2xl font-black text-[10px] uppercase text-white bg-emerald-600 hover:bg-emerald-500 shadow-lg transition-colors">I Confirm - Lock Schedule</button>
                  </div>
              </div>
          </div>
      )}

    </div>
  );
};

export default DepartmentCard;
